<x-layouts.app title="Review moderation"><div class="page-heading"><h1>Review moderation</h1><p>Manage the visibility of customer feedback while retaining its audit history.</p></div><form method="GET" class="d-flex flex-wrap align-items-end gap-2 mb-4"><div><label class="form-label" for="status">Review visibility</label><select id="status" class="form-select" name="status"><option value="">All reviews</option><option value="published" @selected(($filters['status'] ?? '') === 'published')>Published</option><option value="hidden" @selected(($filters['status'] ?? '') === 'hidden')>Hidden</option></select></div><button class="btn btn-primary" type="submit">Apply filter</button></form><div class="surface overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Review</th><th>Customer</th><th>Shop</th><th>Status</th><th class="text-end">Visibility</th></tr></thead><tbody>@forelse($reviews as $review)<tr><td><strong>{{ $review->rating }}/5 stars</strong><br><span class="small text-secondary">{{ $review->comment }}</span></td><td>{{ $review->customer->name }}</td><td>{{ $review->shop->name }}<br><span class="small text-secondary">{{ $review->repairJob->job_number }}</span></td><td class="text-capitalize">{{ $review->status }}</td><td class="text-end"><form method="POST" action="{{ route('admin.reviews.update', $review) }}">@csrf @method('PATCH')<button class="btn btn-sm btn-{{ $review->status === 'published' ? 'outline-danger' : 'success' }}" name="status" value="{{ $review->status === 'published' ? 'hidden' : 'published' }}">{{ $review->status === 'published' ? 'Hide review' : 'Publish review' }}</button></form></td></tr>@empty<tr><td colspan="5" class="p-4 text-secondary">No reviews found.</td></tr>@endforelse</tbody></table></div></div><div class="mt-3">{{ $reviews->links() }}</div></x-layouts.app>
